func Test_WebPubSub_Spec_WhenSerializedToJson_DeserializesAsEqual(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, RunJSONSerializationTestForWebPubSub_Spec)
}

// RunJSONSerializationTestForWebPubSub_Spec runs a test to see if a specific instance of WebPubSub_Spec round trips to JSON and back losslessly
func RunJSONSerializationTestForWebPubSub_Spec(t *rapid.T) {
	subject := WebPubSub_SpecGenerator().Draw(t, "subject")
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		t.Fatal(err)
	}

	// Deserialize back into memory
	var actual WebPubSub_Spec
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		t.Fatal(err)
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		t.Error(result)
	}
}

